function [alb, emi] = zonal_coeffs(lat, doy)
%ZONAL_COEFFS  erp.zonalCoeffs(lat, doy): Knocke's zonal albedo and emissivity at geocentric latitude lat [rad] on day of year doy.
%   lat: real[1] (passed a plain number)
%   doy: real[1] (passed a plain number)
%   returns alb: real[1] (passed a plain number)
%   returns emi: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    alb = 0;
    emi = 0;
    a0 = 0.34;
    a1 = 0.1;
    a2 = 0.29;
    e0 = 0.68;
    e1 = (-(0.07));
    e2 = (-(0.18));
    w = ((2 * pi) / 365.25);
    t0 = 0;
    s = sin(lat);
    p1 = s;
    p2 = (0.5 * (((3 * s) * s) - 1));
    ann = cos((w * (doy - t0)));
    alb = ((a0 + ((a1 * ann) * p1)) + (a2 * p2));
    emi = ((e0 + ((e1 * ann) * p1)) + (e2 * p2));
end
